-- 0234 Restaura monumentos borrados por error en 0233 (nombres genéricos compartidos con capitales)
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Último sub-bloque procesado','Letras E, G, J y M (completado hasta el municipio de Medina-Sidonia, inclusive).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','palacio','Palacio Episcopal','Residencia monumental del siglo XVIII en sillería arenisca y revocos tradicionales de yeso rojo de Albarracín, que destaca por su gran portalada heráldica barroca y un claustro interior porticado de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','iglesia','Iglesia de San Bartolomé','Templo gótico-renacentista modificado en el siglo XVIII que impresiona a nivel mundial por su espectacular torre-fachada barroca, una obra cumbre labrada en ladrillo, yeso y azulejería polícroma con una profusión ornamental barroca sin parangón en Extremadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','catedral','Catedral de San Juan Bautista','Iglesia fortificada del siglo XIII con un impresionante claustro gótico-mudéjar y ventanas de traza renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','monumento','Plaza de España','Espléndido coso porticado portador de balconadas mudéjares de ladrillo, sede histórica del Tribunal de la Inquisición en Extremadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','iglesia','Iglesia de Santiago Apóstol','Templo tardomedieval edificado sobre restos romanos que combina muros de mampostería con una cabecera gótica, sirviendo actualmente de centro de interpretación para el área arqueológica de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28036','iglesia','Iglesia de Santiago Apóstol','Templo parroquial reconstruido en el siglo XVIII de líneas neoclásicas, levantado sobre la base de una ermita barroca anterior, con una sencilla torre de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','iglesia','Iglesia de Santiago Apóstol','Templo parroquial del siglo XVI de estilo renacentista rural herreriano, edificado en recios sillares de granito, que conserva una fachada austera y un coro alto de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28094','iglesia','Iglesia de San Bartolomé','Templo del siglo XV-XVI con transformaciones barrocas, construido en mampostería de piedra rústica berroqueña y gneis, con una espadaña tradicional de dos vanos y coro alto de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','iglesia','Iglesia de Santiago Apóstol','Templo románico de transición (siglo XII-XIII) edificado en piedra berroqueña rústica, que conserva una portada románica de arcos de medio punto con arquivoltas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28171','iglesia','Iglesia de Santiago Apóstol','Monumental templofortaleza del gótico tardío y renacimiento (siglo XVI), edificado íntegramente con grandes sillares de granito berroqueño; catalogado como BIC, posee una imponente torre defensiva de 32 metros y un interior cubierto con bóvedas de crucería estrellada y pinturas murales mudéjares singulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','iglesia','Iglesia de San Miguel','Templo mudéjar que alberga una magnífica cabecera de ladrillo y un interior de gran anchura basilical con un espectacular retablo renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90081','iglesia','Iglesia de San Bartolomé','Pequeño templo de arquitectura barroca popular (siglo XVII) edificado con piedras de granito rústicas de la sierra de Gredos, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05052','iglesia','Iglesia de Santiago Apóstol','Templo herreriano del siglo XVI levantado en sillería de granito serrano; de líneas sobrias y proporciones geométricas limpias, posee muros desnudos y espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','iglesia','Iglesia de Santiago Apóstol','Monumental templo clasicista y herreriano del siglo XVI diseñado por Francisco de Mora y Herrera el Mozo; conocida como la "Catedral de la Sierra", destaca por sus proporciones catedralicias, sus colosales pilares toscanos de granito y sus bóvedas limpias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10022','iglesia','Iglesia de Santiago Apóstol','Templo mudéjar tardío del siglo XVI construido en mampostería de granito y pizarra que alberga un sobrio púlpito de cantería y una espadaña de dos cuerpos rematada por pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','iglesia','Iglesia de San Bartolomé','Monumental templo góticorenacentista iniciado en el siglo XVI con sillería de granito berroqueño de impecable factura que presenta una imponente fachada de corte herreriano y un espacioso interior de tres naves cubiertas por complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','catedral','Catedral de Santa María de la Asunción','Obra cumbre que fusiona el gótico flamígero, el plateresco y el barroco (siglos XV-XVIII); destaca su espectacular portada septentrional con filigranas de piedra tallada, su imponente torre campanario que domina la llanura del Alagón y un retablo mayor barroco monumental de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','palacio','Palacio Episcopal','Edificio civil residencial barroco del siglo XVII de grandes proporciones construido en ladrillo con una sobria fachada conventual clasicista y escudos de armas obispales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','iglesia','Iglesia de San Pedro','Templo románico de finales del siglo XII modificado en el periodo barroco utilizando aparejo mixto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','iglesia','Iglesia de San Miguel','Monumental obra del siglo XIII al XVI de proporciones catedralicias; levantada íntegramente con sillería caliza, destaca por su portada gótica, sus altísimas bóvedas de crucería y un colosal retablo mayor renacentista plateresco de gran valor artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','iglesia','Iglesia de San Miguel','Joya del románico clásico (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada norte con arquerías de medio punto sobre columnas pareadas con capiteles magníficamente esculpidos y su ábside semicircular intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40208','iglesia','Iglesia de Santiago','Templo románico de transición (siglo XII) profundamente reformado; alberga en su interior un presbiterio con un retablo de piedra caliza policromado de gran valor para la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50093','iglesia','Iglesia de San Miguel','Templo neoclásico integrado simétricamente en el propio entramado porticado de la plaza monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','iglesia','Iglesia de San Miguel','Joya del románico de transición (siglo XII); destaca por su espectacular ábside semicircular de sillería impecable y, en su interior, un conjunto de pinturas murales góticas del siglo XIV de gran valor para la arqueología aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','palacio','Palacio Episcopal','Majestuoso e histórico complejo residencial de los obispos de Tarazona erigido a partir del siglo XIV sobre el antiguo alcázar musulmán; colosal palacio que corona la ciudad colgada sobre el río Queiles, edificado en sillería de piedra caliza calavera y ladrillo, destacando su espectacular Salón de los Obispos decorado con un artesonado mudéjar policromado y retratos de los prelados, y su fachada renacentista con arquerías aragonesas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','iglesia','Iglesia de San Pedro','Espléndido templo renacentista diseñado por los arquitectos Francisco del Castillo y Andrés de Vandelvira, con una severa portada clasicista de líneas geométricas impecables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','palacio','Palacio Municipal (Ayuntamiento)','Joya de la arquitectura civil renacentista plateresca del siglo XVI; presenta una grandiosa fachada simétrica que alberga una colosal portada y escudos de armas nobiliarios tallados en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','monumento','Muelle del Tinto (Cargadero de Mineral de la Compañía de Riotinto)','Monumental e histórica infraestructura de la arquitectura industrial de finales del siglo XIX proyectada por la escuela de Eiffel, consistente en un colosal viaducto y muelle marítimo de hierro calado y madera que se adentra de forma monumental en la ría de Huelva asentado sobre recios pilares de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','catedral','Santa Iglesia Catedral de Nuestra Señora de la Merced','Monumental fábrica de estilo barroco academicista del siglo XVII erigida como iglesia del convento de los mercedarios, que destaca por su espaciosa planta basilical sostenida por pilares toscanos y una espectacular fachada monumental de gran plasticidad esculpida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','iglesia','Santuario de Nuestra Señora de la Cinta','Joya monumental gótico-mudéjar de los siglos XV y XVI exenta sobre el cabezo del Conquero, edificado en ladrillo visto y mampostería encalada que conserva de forma magistral sus tres naves techadas por armaduras de madera y un claustro tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','monumento','Barrio Obrero / Barrio Reina Victoria','Espectacular y colosal conjunto residencial y urbanístico de la arquitectura civil británica de principios del siglo XX, constituido por decenas de viviendas de estilo victoriano con entramados de madera pintada y cubiertas inclinadas de teja que configuran un paisaje único en la urbe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','iglesia','Iglesia de San Pedro','El templo cristiano más antiguo de la capital, datado en el siglo XV de estilo góticomudéjar primitivo, edificado sobre los restos de una antigua mezquita andalusí con una esbelta torre campanario barroca de ladrillo visto moldurado profusamente decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','iglesia','Basílica de Santa María la Mayor','Obra cumbre del gótico valenciano construida en cantería caliza de primer orden que exhibe una fachada monumental con las puertas de los Apóstoles y de las Vírgenes, una espectacular escalera de coro de caracol exenta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','iglesia','Iglesia de San Pedro','Antiguo templo de origen románico y mudéjar del siglo XII reformado en el siglo XIV que se estructura sobre los restos de una antigua sinagoga medieval empleando piedra rústica y ladrillo visto, destacando por su portada occidental de arcos apuntados doblados y sus inscripciones epigráficas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','iglesia','Iglesia de San Miguel','Templo de tradición mudéjar rural edificado en el siglo XVI con muros portantes de tapial arcilloso y cajones de ladrillo macizo visto, cuyo interior atesora un artesonado de madera de pino estructurado mediante vigas de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','iglesia','Iglesia de Santiago Apóstol','Templo románico de finales del siglo XII levantado con excelente sillería caliza dorada y mampostería pizarrosa que destaca universalmente por su "Puerta del Perdón", la única portada junto a la de la Catedral de Santiago de Compostela donde los peregrinos impedidos físicamente pueden ganar el jubileo jacobeo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','iglesia','Iglesia de Santiago','Obra cumbre del románico pleno del siglo XII declarada Monumento Nacional en la ruta del Camino de Santiago Francés que destaca universalmente por el friso escultórico de su fachada occidental tallado en piedra arenisca dorada, donde un Pantocrátor rodeado por el Tetramorfos y los veinticuatro ancianos del Apocalipsis exhibe una finura técnica inigualable sobre una portada de arcos de medio punto jalonada por el célebre apostolado de los músicos y artesanos medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','iglesia','Iglesia de San Pedro','Templo monumental de transición gótico-renacentista del siglo XVI levantado en cantería caliza bien escuadrada que presenta una planta de tres naves separadas por pilares fasciculados, albergando en su interior el suntuoso retablo mayor ejecutado por el maestro Francisco Giralte con policromías de la escuela vallisoletana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','iglesia','Iglesia de San Pedro','Templo monumental de los siglos XV y XVI erigido con excelente cantería caliza calavera que presenta una fachada neoclásica dominada por la célebre "Estrella de Campos", una imponente y esbelta torre campanario de traza gótico-flamígera de más de sesenta metros de altura calada con tracerías finas, cuyo interior atesora un espectacular artesonado mudéjar policromado en su coro alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','iglesia','Iglesia de San Pedro','Magna iglesia fortificada gótica del siglo XIV declarada Monumento Nacional que domina el litoral costero desde un promontorio urbano, erigida con una masiva y recia sillería caliza gris de montaña que destaca exteriormente por su aspecto inexpugnable de torre fortificada, albergando en su interior de nave única un suntuoso retablo mayor de la escuela plateresca ejecutado por el maestro Juan de de Ancheta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','catedral','Catedral de Santa María de la Asunción','Magna basílica del siglo XVI de estilo gótico renacentista columnario (estilo hallenkirche) levantada en excelente sillería caliza prepirenaica que presenta tres naves de igual altura cubiertas por bóvedas de crucería estrellada apoyadas sobre colosales columnas exentas, albergando en su presbiterio un espectacular retablo mayor romanista ejecutado en madera noble por el maestro Damián Forment.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','iglesia','Iglesia de San Pedro','Templo de origen románico profundamente modificado en el periodo mudéjar y barroco que presenta una nave única con una robusta portada de arcos apuntados doblados, rematada exteriormente por una esbelta torre campanario de ladrillo mudéjar con arquerías ciegas de gran finura constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19252','iglesia','Iglesia de San Pedro','Obra renacentista del siglo XVI edificada en aparejo toledano combinando hileras de ladrillo macizo y cajones de mampostería caliza, dotada de una portada clasicista adintelada flanqueada por pilastras planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19263','iglesia','Iglesia de San Miguel','Construcción rural barroca del siglo XVII ejecutada en aparejo toledano combinando hiladas de ladrillo macizo y cajones de mampostería basta, rematada por una modesta espadaña de dos vanos en el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19281','iglesia','Iglesia de San Miguel','Edificación del siglo XVI construida en sillería arenisca y mampostería, destacando su ábside cuadrangular y una portada renacentista purista de arco de medio punto flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19326','iglesia','Iglesia de San Bartolomé','Fábrica renacentista del siglo XVI ejecutada en mampostería caliza calavera con refuerzo de sillares en las esquinas, notable por su portada meridional de líneas clasicistas bajo arco de medio punto y su severa torre campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','iglesia','Iglesia de San Miguel','Excepcional obra monumental del gótico del siglo XV construida en sillería arenisca, que conserva adosada una espectacular torre-fortaleza románica del siglo XII de planta cuadrangular con arquerías ciegas de influjo mudéjar y un soberbio retablo mayor plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42020','iglesia','Iglesia de San Miguel','Joya excepcional del románico mudéjar de finales del siglo XII ejecutada en sillería caliza regular, célebre por su espectacular linterna exterior calada y una cúpula interior de nervios entrecruzados de claro influjo cordobés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42052','iglesia','Iglesia de San Pedro','Obra cumbre del románico soriano del siglo XII erigida en sillería regular, célebre por su magnífica galería porticada meridional con arquerías de medio punto apoyadas sobre columnas geminadas y haces de columnas torsas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42053','iglesia','Iglesia de San Pedro','Edificación de origen románico reformada en el período barroco en mampostería caliza,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42062','iglesia','Iglesia de San Pedro','Edificación del siglo XVI construida en sillería arenisca y mampostería integrada en el paisaje, destacando su ábside cuadrangular y una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42070','iglesia','Iglesia de San Pedro','Pequeño oratorio de planta rectangular en mampostería vista y sillares de refuerzo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42087','iglesia','Iglesia de San Miguel','Estructura de arquitectura popular castellana del siglo XVII levantada en aparejo de canto rodado y sillarejo, rematada por una modesta espadaña de dos vanos y un porche sencillo de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42096','palacio','Palacio de los Condes de Gómara','Casona noble señorial del siglo XVI construida en excelente sillería arenisca, mostrando una fachada monumental con escudo heráldico moldurado y balconadas de forja artística sobre repisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','iglesia','Iglesia de San Miguel','Obra cumbre de la arquitectura románica peninsular del siglo XI (año 1081) construida en excelente sillería caliza regular, universal por poseer la galería porticada románica más antigua conservada en España con arquerías de medio punto apoyadas sobre capiteles historiados de influencia califal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42184','iglesia','Iglesia de Santiago Apóstol','Fábrica del siglo XVI ejecutada en mampostería de piedra arenisca y caliza local, caracterizada por su presbiterio de planta rectangular reforzado exteriormente por estribos y una modesta espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42196','iglesia','Iglesia de San Pedro','Edificio integrado en la arquitectura serrana de las Tierras altas del siglo XVI, construido con gruesos paramentos de lajas de pizarra rústica y argamasa, rematado por una espadaña de pizarra de dos vanos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42204','iglesia','Iglesia de San Bartolomé','Fábrica renacentista de finales del siglo XVI ejecutada en mampostería caliza con sillares de cantería regular en las esquinas, notable por su ábside de paños con contrafuertes y un interior cubierto por bóvedas de crucería nervada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44024','iglesia','Iglesia de San Bartolomé','Templo parroquial barroco del siglo XVII ejecutado en aparejo toco de arcilla y sillarejo calcáreo, que alberga una nave única con coro de madera y viguería de pino serrano vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44036','iglesia','Iglesia de San Bartolomé','Modesta construcción rural del siglo XVII edificada en piedra basta del terreno con esquinas de piedra labrada, caracterizada por su planta rectangular unicelular con tejado a dos aguas de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','iglesia','Iglesia de San Bartolomé','Magna fábrica barroca del siglo XVIII ejecutada en excelente cantería caliza regular, notable por su monumental portada-retablo flanqueada por columnas salomónicas profusamente esculpidas y un espacioso interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','iglesia','Iglesia de San Miguel','Magna edificación gótica del siglo XIV erigida en sillería caliza regular, célebre por su monumental rosetón calado en la fachada occidental, su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44102','iglesia','Iglesia de San Miguel','Estructura de arquitectura popular del siglo XVII levantada con aparejo mixto de arcilla y mampostería basta, rematada por una modesta espadaña de dos vanos en la fachada occidental de tradición serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44119','iglesia','Iglesia de San Pedro','Fábrica rural de la Sierra de Albarracín del siglo XVII edificada con gruesos paramentos de mampostería caliza y piedra arenisca de rodeno rojo, rematada por una modesta espadaña de dos vanos dispuesta sobre el imafronte occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44120','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVII integrado en la arquitectura serrana del Alto Tajo, edificado con paramentos toscos de piedra calcárea del terreno y viguería de pino, que alberga una pila bautismal monolítica medieval de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44123','iglesia','Iglesia de San Miguel','Templo renacentista del siglo XVI edificado en regular sillarejo calizo, caracterizado por su presbiterio de planta rectangular reforzado por estribos oblicuos y su portada meridional de arco de medio punto moldurado flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','iglesia','Iglesia de San Miguel','Templo de transición góticorenacentista del siglo XVI levantado en cantería bien escuadrada, notable por su ábside poligonal con bóvedas de crucería estrellada y su gran torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44136','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVI levantado en regular cantería caliza con potentes estribos exteriores, notable por su presbiterio cubierto con bóvedas de crucería estrellada y una portada clasicista bajo arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44141','iglesia','Iglesia de Santiago Apóstol','Fábrica gótica del siglo XIV labrada en excelente cantería de piedra arenisca regular, dotada de un interior de nave única con bóvedas de crucería nervada y una portada meridional de tres arquivoltas apuntadas de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44146','iglesia','Iglesia de San Bartolomé','Templo renacentista del siglo XVI edificado en sillería caliza regular, notable por su ábside poligonal con contrafuertes oblicuos y su portada meridional plateresca flanqueada por pilastras molduradas con relieves de grutescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44159','iglesia','Iglesia de San Pedro','Fábrica rural de la Sierra de Albarracín del siglo XVII construida en sillería de piedra arenisca de rodeno rojo y mampostería, provista de una nave única con cabecera de paños y una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44163','iglesia','Iglesia de San Miguel','Fábrica de tradición barroca del siglo XVIII integrada en la Sierra de Albarracín, levantada en mampostería basta de piedra arenisca roja (pétreo rodeno) y caliza local, provista de una torre campanario de dos cuerpos con remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44168','iglesia','Iglesia de San Bartolomé','Templo del siglo XVI reformada en el barroco levantado en sillería caliza y mampostería regular, caracterizado por su presbiterio de planta rectangular y una portada purista de arco de medio punto flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44185','iglesia','Iglesia de San Bartolomé','Templo del gótico tardío del siglo XVI edificado en regular sillería caliza, notable por su presbiterio de planta poligonal con contrafuertes oblicuos exteriores y un interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44190','iglesia','Iglesia de San Miguel','Templo renacentista del siglo XVI construido en sillería caliza calavera, provisto de un presbiterio poligonal reforzado por potentes estribos y una portada meridional purista flanqueada por pilastras cajeadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44198','iglesia','Iglesia de San Bartolomé','Templo del siglo XVI reformado en el barroco levantado en sillería de piedra arenisca de rodeno y caliza, caracterizado por su presbiterio de planta rectangular y una pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44203','iglesia','Iglesia de San Miguel','Modesta construcción rural del siglo XVII edificada en aparejo tosco de caliza con esquinas de sillería de refuerzo, rematada por una pequeña espadaña de un vano dispuesta sobre los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44220','iglesia','Iglesia de San Pedro','Edificación del siglo XVI construida en aparejo de sillarejo calizo con esquinas de sillería regular, dotada de una portada meridional purista bajo arco de medio punto y una pila bautismal románica troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44224','iglesia','Iglesia de San Miguel','Templo barroco del siglo XVII ejecutado en mampostería tosca de caliza con refuerzo de bloques de cantería en los ángulos, caracterizado por su espadaña escalonada barroca dispuesta sobre el muro occidental de los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44225','iglesia','Iglesia de San Pedro','Magna fábrica gótica del siglo XIV labrada en excelente cantería de piedra arenisca regular de la comarca del Matarraña, singular por poseer un ábside poligonal con gárgolas escultóricas y ventanales apuntados de finísima tracería gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44221','iglesia','Iglesia de San Miguel','Templo renacentista del siglo XVI construido en regular cantería caliza, notable por su elegante torre campanario barroca de ladrillo vista diseñada con cuerpos decrecientes de tradición mudéjar y relieves geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44229','iglesia','Iglesia de San Miguel','Templo del siglo XVI reformado en el barroco levantado en sillería de piedra arenisca de rodeno y caliza calavera, caracterizado por su presbiterio de planta rectangular y una robusta torre campanario de planta cuadrangular adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44232','iglesia','Iglesia de San Pedro','Magna fábrica barroca del siglo XVIII construida en excelente sillería caliza y ladrillo vista, notable por su esbelta torre campanario que combina un primer cuerpo cúbico pétreo con remates superiores ochavados de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44247','iglesia','Iglesia de San Miguel','Templo barroco de grandes proporciones del siglo XVIII erigido en excelente cantería arenisca regular, notable por su monumental portadaretablo churrigueresca profusamente esculpida y un espacioso interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVI levantado en aparejo toledano rústico con esquinas de sillería de refuerzo, caracterizado por su presbiterio de planta rectangular con techumbre de madera de tradición mudéjar de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90296','iglesia','Iglesia de Santiago Apóstol','Fábrica renacentista de grandes proporciones del siglo XVI atribuida a las trazas de Alonso de Covarrubias, construida en sillería de granito berroqueño, notable por su ábside poligonal y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90297','iglesia','Iglesia de San Bartolomé','Templo del siglo XVI levantado en cantería de granito y mampostería, caracterizado por su presbiterio de planta cuadrangular reforzado exteriormente por potentes estribos y una torre campanario robusta de paramentos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90303','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVI levantado en aparejo de ladrillo y mampostería, caracterizado por su ábside de planta poligonal mudéjar con arquerías ciegas dobladas de ladrillo y una pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45019','iglesia','Iglesia de Santiago Apóstol','Fábrica barroca del siglo XVII levantada en aparejo toledano combinando rafas de ladrillo macizo y cajones de mampostería, dotada de una torre campanario de planta cuadrangular adosada con vanos moldurados y un interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45035','iglesia','Iglesia de Santiago Apóstol','Edificación parroquial del siglo XVI ejecutada en mampostería rústica y sillares de refuerzo graníticos, caracterizada por su sencillez estructural de nave única con coro alto de madera y arco triunfal de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45042','iglesia','Iglesia de Santiago Apóstol','Fábrica renacentista de finales del siglo XVI levantada en aparejo toledano rústico con sillares graníticos de refuerzo en los ángulos, que cuenta con una espadaña de dos cuerpos decrecientes dispuesta en el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45055','iglesia','Iglesia de Santiago Apóstol','Templo del gótico tardío y transición renacentista del siglo XVI edificado en regular sillería y aparejo toledano, notable por su imponente ábside de paños con contrafuertes y un interior cubierto con bóvedas de crucería estrellada de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45156','iglesia','Iglesia de Santiago Apóstol','Imponente templo del gótico tardío y transición renacentista edificado en cantería caliza de primer orden que presenta tres naves a igual altura sostenidas por pilares fasciculados y un soberbio ábside poligonal cubierto por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','iglesia','Iglesia de Santo Domingo','Templo del barroco clasicista proyectado con una espaciosa planta de cruz latina y muros de mampostería toledana que exhibe una fachada sobria con una portada monumental flanqueada por columnas adosadas y hornacinas decorativas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16190','iglesia','Iglesia de Santiago Apóstol','Monumental templo columnario de proporciones catedralicias trazado por Andrés de Vandelvira en el siglo XVI que presenta tres naves a igual altura sostenidas por pilares fasciculados colosales, un crucero magnífico cubierto por bóvedas de crucería estrellada y un retablo mayor barroco de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13047','iglesia','Convento de la Merced','Complejo monacal del siglo XVII edificado en ladrillo visto y piedra que presenta una severa iglesia de líneas herrerianas con fachada adintelada rematada por un frontón partido.','inventario_monumentos_pdf');
