INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','iglesia','Basílica de Santa María','Magna obra del barroco clasicista valenciano construida entre los siglos XVII y XVIII que exhibe una espectacular fachada-retablo profusamente decorada con columnas salomónicas esculpidas por Nicolás de Bussy y un interior cupulado universal donde se representa anualmente el Misteri d''Elx.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','iglesia','Iglesia de San Bartolomé','Joya monumental de la arquitectura militar y religiosa del gótico tardío valenciano del siglo XVI, erigida enteramente en sillería de piedra tosca local de color dorado que destaca por sus recios muros provistos de matacanes, saeteras defensivas, almenas superiores y un interior de inmensa nave única abovedada.','inventario_monumentos_pdf');
