INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','iglesia','Iglesia de Santiago','Magna obra del gótico final y transición renacentista del siglo XV construida en cantería caliza calavera que exhibe tres elevadas naves sustentadas por columnas cilíndricas colosales, un magnífico crucero plateresco y un espectacular retablo mayor pictórico.','inventario_monumentos_pdf');
