INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','catedral','Santa Iglesia Catedral de la Encarnación','Monumental templo que fusiona el gótico, el renacimiento y el fastuoso barroco internacional proyectado por Diego de Siloé y Vicente Acero en sillería de cantería caliza de primer orden, destacando su monumental fachada barroca esculpida, pilares jónicos colosales y una espectacular cúpula sobre el crucero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','iglesia','Iglesia de Santiago','Magna fábrica gótico-mudéjar del siglo XVI construida en cantería caliza calavera que exhibe una espectacular fachada plateresca cobijada bajo arco de triunfo atribuida a Diego de Siloé y un interior techado por una colosal armadura de madera de par y nudillo policromada.','inventario_monumentos_pdf');
