INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','iglesia','Iglesia de San Pedro','Magna fábrica del barroco triunfante del siglo XVIII erigida en cantería y ladrillo visto que deslumbra por su espaciosa planta basilical, un fastuoso altar mayor dorado churrigueresco y su colosal torre campanario conocida como "La Giraldilla" por su similitud con la de Sevilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','monumento','Último sub-bloque procesado','Letra C (completado hasta el municipio de Cazalla de la Sierra, inclusive).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','iglesia','Iglesia de Santiago','Magna fábrica del gótico final isabelino y transición renacentista construida en cantería caliza de primer orden under trazas de la escuela cordobesa y sevillana, que exhibe tres elevadas naves cubiertas por intrincadas bóvedas de crucería estrellada compleja.','inventario_monumentos_pdf');
