INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41087','iglesia','Iglesia de San Pedro','Joya monumental universal de la arquitectura mudéjar del siglo XIII declarada Monumento Nacional, erigida enteramente en ladrillo visto macizo de la comarca del Aljarafe sobre las ruinas de una antigua fortificación almohade de la que conserva de forma','inventario_monumentos_pdf');
