INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06029','iglesia','Iglesia de San Bartolomé','Templo renacentista castellano modificado en el siglo XVIII que muestra muros de mampostería vista combinada con hiladas de ladrillo y una cabecera cupulada sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06030','iglesia','Iglesia de Santiago Apóstol','Inmueble del siglo XV edificado en las estribaciones del castillo que conserva interesantes arcos mudéjares apuntados de ladrillo y una techumbre de madera restaurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06034','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XV edificado en estilo mudéjar tardío con muros de mampostería encalada que destaca por su coro alto con balaustrada de madera labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06039','iglesia','Iglesia de San Bartolomé','Templo renacentista castellano ordinario del siglo XVI ejecutado en mampostería vista con refuerzos de sillería en las esquinas que muestra una nave única con arcos de cantería y una torre adosada a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06009','iglesia','Iglesia de Santiago Apóstol','Monumental templo gótico-renacentista iniciado en el siglo XVI que presenta una imponente fachada de corte herreriano labrada en granito berroqueño y un espacioso interior de tres naves con bóvedas de crucería estrellada soportadas por pilares cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06049','iglesia','Iglesia de San Bartolomé','Templo del siglo XVI edificado en mampostería y cantería que cuenta con una majestuosa portada renacentista de influencia portuguesa y una cabecera poligonal cubierta por complejas bóvedas estrelladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06132','iglesia','Iglesia de Santiago Apóstol','Templo renacentista del siglo XVI construido con sillarejos de granito y mampostería que presenta una interesante portada renacentista de orden plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90488','iglesia','Iglesia de Santiago','Joya de la arquitectura románicomudéjar del siglo XII construida íntegramente en ladrillo visto sobre zócalos de mampostería que destaca por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','iglesia','Iglesia de Santiago','Templo románico de finales del siglo XII construido íntegramente en sillería granítica que destaca por su ábside semicircular perfecto, sus tramos de arquerías ciegas sobre columnas adosadas y una rica iconografía en capiteles zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','iglesia','Iglesia de Santiago','Joya del románico urbano de finales del siglo XII que resalta por su fachada occidental con una magnífica portada de arquivoltas historiadas, su ábside semicircular perfecto decorado con arquerías ciegas y una estatua sedente de Santiago Apóstol en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32088','iglesia','Iglesia de San Miguel','Templo parroquial del siglo XVIII adscrito al barroco rural del valle del Sil que exhibe una fachada sobria de cantería, una portada de arco de medio punto flanqueada por pilastras molduradas y una esbelta espadaña de doble vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','palacio','Palacio Episcopal','Edificio civil de fábrica barroca del siglo XVIII que delimita la plaza catedralicia y exhibe un monumental portalón de acceso adintelado con los grandes blasones heráldicos de los obispos labrados minuciosamente en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27049','iglesia','Iglesia de San Pedro','Edificación románica de finales del siglo XII reconstruida en el nuevo emplazamiento de la villa que conserva una magnífica portada occidental con arquivoltas profundas labradas sobre capiteles historiados de gran valor artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','iglesia','Iglesia de San Pedro','Templo parroquial de estilo neoclásico construido en el siglo XIX que destaca por su monumental fachada flanqueada por pilastras, un gran frontón triangular','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','iglesia','Iglesia de San Pedro','Monumental templo barroco edificado en el siglo XVIII por la saga de arquitectos Morató que destaca por su fachada de sillería de piedra arenisca local con portada neoclásica moldurada, un amplio interior de tres naves y una esbelta torre-campanario que corona el término.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08292','iglesia','Iglesia de San Bartolomé','Templo parroquial de origen medieval profundamente reformado en el siglo XVII bajo las directrices del barroco rural que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','palacio','Palacio Episcopal','Residencia e institución eclesiástica gótica del siglo XIV profundamente reformada en los siglos XVII y XVIII que presenta un claustro central de arcos apuntados, portales dovelados de medio punto y amplias salas que custodian el tesoro y el archivo diocesano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','iglesia','Iglesia de San Miguel','Templo de base medieval profundamente reconstruido en el siglo XVII en estilo barroco rural de líneas severas que exhibe una fachada monumental enlucida con portal de cantería moldurada, contrafuertes robustos exteriores y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','iglesia','Iglesia de San Pedro','Templo parroquial de estilo gótico tardío construido en el siglo XVI que presenta una amplia nave con bóveda de crucería, una fachada sobria con portalada renacentista de sillería caliza y un robusto campanario cuadrangular adosado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90615','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una monumental fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25023','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90620','iglesia','Iglesia de San Miguel','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y una esbelta torrecampanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25073','iglesia','Iglesia de San Miguel','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25074','iglesia','Iglesia de San Miguel','Templo parroquial de origen románico profundamente transformado en el periodo barroco (siglo XVIII) que exhibe una fachada de sillería vista con portada clasicista moldurada, un interior de nave única y un recio campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','iglesia','Iglesia de San Pedro','Edificio religioso de traza gótica (siglo XIV) que presenta una imponente nave única de gran anchura con capillas laterales entre contrafuertes robustos, una portada con arquivoltas apuntadas y una robusta torrecampanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25131','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior cerca de la desembocadura del río Cinca en el Segre que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25135','iglesia','Iglesia de San Miguel','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada que corona el perfil urbano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25189','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90624','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25211','iglesia','Iglesia de San Pedro','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25248','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35031','iglesia','Iglesia de San Miguel','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90646','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería vista de líneas clásicas muy sobrias con portada moldurada flanqueada por pilastras y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90649','iglesia','Iglesia de San Pedro','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90655','iglesia','Iglesia de San Pedro','Templo parroquial levantado a finales del siglo XIX en un riguroso estilo neogótico que cuenta con una amplia nave longitudinal con bóvedas de crucería calada, una fachada de sillería vista de piedra caliza (marès) y un esbelto campanario calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','iglesia','Iglesia de San Miguel','Magna iglesia de traza gótica tardía iniciada en el siglo XVI que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos provistas de ventanales calados y una fastuosa fachada occidental barroca de sillería calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','iglesia','Iglesia de San Miguel','Monumental basílica reedificada en el siglo XIX en estilo neoclásico por el arquitecto Isidro González Velázquez que destaca por su imponente fachada de sillería caliza vista de grandes dimensiones flanqueada por pilastras, un amplio interior de tres naves y un robuso campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48018','iglesia','Iglesia de San Pedro','Monumental templo gótico renacentista del siglo XVI levantado en robusta sillería caliza gris. Presenta una volumetría exterior imponente reforzada por contrafuertes que configuran capillas hornacinas interiores. Las cubiertas se resuelven mediante un complejo entramado de bóvedas de crucería estrellada con terceletes y claves talladas que apean sobre ménsulas empotradas en los muros de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','iglesia','Iglesia de San Pedro','Monumental edificio religioso neoclásico construido a mediados del siglo XIX por el arquitecto Antonio de Echevarría tras la destrucción del templo barroco anterior. Destaca su severa fachada de sillería fina labrada con un gran pórtico clasicista soportado por columnas jónicas y un interior de tres amplias naves cubiertas con bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','iglesia','Basílica de Santa María','Soberbio templo gótico edificado entre los siglos XV y XVI empleando sillería caliza dorada de gran formato. Presenta planta de tres naves de gran altura divididas por pilares fasciculados que recogen los nervios de complejas bóvedas de crucería estrellada con claves heráldicas esculpidas. El exterior destaca por su monumental triforio calado, gárgolas expresivas, contrafuertes robustos y una imponente torre campanario de transición al barroco clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48085','iglesia','Iglesia de San Pedro','Templo edificado en el siglo XVI en estilo gótico tardío con profundas transformaciones barrocas en el siglo XVIII. Fábrica ejecutada en mampostería arenisca con esquinazos de sillería caliza compacta. Alberga una espaciosa nave única cubierta por soluciones de crucería estrellada cuyos nervios apean en ménsulas molduradas empotradas, destacando su pórtico perimetral de madera tradicional vasca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90257','iglesia','Iglesia de San Pedro','Templo columnario o de salón (Hallenkirche) edificado en el siglo XVI en sillería caliza de gran formato. Su espacio interior está dividido en tres naves de igual altura mediante esbeltas columnas jónicas exentas de fuste liso que recogen los nervios de un magnífico entramado de bóvedas de crucería estrellada con claves decoradas y relieves figurativos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20037','iglesia','Iglesia de San Miguel','Pequeño templo de carácter rural y tipología tradicional de montaña, reedificado en el siglo XVI sobre estructuras medievales preexistentes. Su fábrica de mampostería regular presenta contrafuertes y vanos rematados en sillería arenisca compacta. El interior alberga una nave única de gran amplitud cubierta por falsas bóvedas de madera en forma de artesa apoyadas en cornisa corrida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90705','iglesia','Iglesia de San Pedro','Templo edificado en el siglo XIV en estilo gótico pirenaico rural y reformado profundamente en el siglo XVI empleando sillería caliza compacta y mampostería gruesa. Alberga una nave única con cabecera poligonal cubierta por un intrincado entramado de bóvedas de crucería estrellada. El elemento singular exterior es su robusta torre campanario de planta cuadrada que ejerce funciones de vigía sobre el valle de Salazar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33003','iglesia','Iglesia de San Miguel','Monumental templo edificado originalmente en el siglo XIV en estilo gótico y profundamente reformado en el siglo XVI. Su fábrica exenta está ejecutada en sillería caliza perfectamente regularizada. Presenta planta de nave única de gran amplitud con capillas entre contrafuertes, cubierta con bóvedas de crucería estrellada compleja. Destaca en su presbiterio el monumental retablo mayor, obra cumbre del escultor renacentista Juan de Anchieta, y una singular pila bautismal gótica de piedra caliza profusamente tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31038','iglesia','Iglesia de San Pedro','Edificio eclesial del gótico inicial edificado en el siglo XIII en sillería caliza compacta. Presenta una fisonomía exenta severa con ventanales ojivales calados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33007','iglesia','Iglesia de San Miguel','Templo de origen románico profundamente transformado en época gótica, levantado en robusto aparejo de sillería perfectamente regularizada. Su elemento culminante es la fastuosa portada septentrional románica, que constituye una de las obras cumbres de la escultura monumental del siglo XII; presenta un arco apuntado abocinado con cinco arquivoltas profusamente talladas que envuelven un tímpano monumental donde se escenifica la Psicostasis (el pesaje de las almas) y la Majestad del Señor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47114','iglesia','Iglesia de San Pablo','Monumental convento gótico-mudéjar fundado en el siglo XIV por el infante Don Juan Manuel, levantado rítmicamente en ladrillo visto y sillería en las zonas nobles. Su cabecera absidial gótica exterior destaca por sus ventanales ojivales calados, mientras que su interior acoge la espectacular capilla de los Manuel, una joya renacentista plateresca del siglo XVI ejecutada en finísima piedra caliza tallada con yeserías políclomas e intrincados casetones decorativos de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47086','iglesia','Iglesia de Santiago Apóstol','Monumental edificio góticorenacentista comenzado en el siglo XVI por Rodrigo Gil de Hontañón, que muestra una imponente fachada principal de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47104','iglesia','Iglesia de San Miguel','Templo mudéjar y gótico edificado en el siglo XIV adosado a la propia muralla defensiva. Su elemento singular es la cripta subterránea de la Virgen de la Soterraña, cubierta con bóvedas de crucería y yeserías mudéjares caladas. La iglesia superior cuenta con un ábside poligonal con arquillos ciegos rítmicos y cubiertas resueltas mediante una armadura de madera vista policromada.','inventario_monumentos_pdf');
